function renderBestiaryContent(){

    const allZoneArrays=[
        forestMonsters,
        desertMonsters,
        iceMountainMonsters,
        zone4Monsters,
        zone5Monsters,
        zone6Monsters,
        zone7Monsters,
        zone8Monsters
    ];


    const seenNames=
        new Set();


    let html=
        "";


    allZoneArrays.forEach(
        zoneArray=>{

            zoneArray.forEach(
                monster=>{

                    if(
                        seenNames.has(
                            monster.name
                        )
                    ){
                        return;
                    }


                    seenNames.add(
                        monster.name
                    );


                    const entry=

                        bestiaryData[
                            monster.name
                        ];


                    const element=

                        elementDatabase[
                            monster.element
                        ]
                        ||
                        elementDatabase.fire;


                    html+=

                        '<div class="home-feature-row">'+

                        "<span>"+

                        (
                            entry && entry.seen
                            ?
                            getElementIconHTML(
                                monster.element
                            )+
                            ""+monster.name
                            :
                            "ï¼Ÿï¼Ÿï¼Ÿ"
                        )+

                        "</span>"+

                        "<span>"+

                        (
                            entry && entry.seen
                            ?
                            "æ“Šæ®º"+(entry.kills||0)
                            :
                            "æœªé‡è¦‹"
                        )+

                        "</span>"+

                        "</div>";

                }
            );

        }
    );


    return html;

}


