    const el=$("inventoryStats");
    if(!el) return;

    if(!stats){
        el.innerHTML='<div class="inventory-empty-character">ç¬¬ä¸‰è§’è‰²å°šæœªå»ºç«‹</div>';
        return;
    }

    /*
       V77ï¼š
       èƒŒåŒ…å¸¸é§è³‡è¨Šåªç•™ HP / SPã€‚
       å…¶ä»–èƒ½åŠ›æ”¹ç”±ç«‹ç¹ªå³ä¸Šè§’æ”¾å¤§é¡é–‹å•Ÿè©³ç´°è³‡è¨Šã€‚
    */
