function getStatText(stats){

    if(
        !stats ||
        Object.keys(stats).length===0
    ){

        return"æ²’æœ‰é¡å¤–èƒ½åŠ›åŠ æˆã€‚";

    }


    const names = {

        attack:"æ”»æ“Š",

        vitality:"é«”è³ª",

        energy:"èƒ½é‡",

        intelligence:"æ™ºåŠ›",

        spirit:"ç²¾ç¥ž",

        agility:"æ•æ·",

        maxHP:"æœ€å¤§HP",

        maxSP:"æœ€å¤§SP",

        defense:"é˜²ç¦¦"

    };


    let html="";


    Object.keys(stats)
    .forEach(key=>{

        const value =
            stats[key];


        if(!value){
            return;
        }


        html +=

        `
        <div>
            ${names[key]||key}ï¼š
            <b>+${value}</b>
        </div>
        `;

    });


    return html ||
        "æ²’æœ‰é¡å¤–èƒ½åŠ›åŠ æˆã€‚";

}


