function equipSelectedItem(){

    const button =
        $("itemEquipButton");


    if(button.dataset.slot){

        unequipItem(
            button.dataset.slot
        );

        return;

    }


    if(
        selectedInventorySlot===null
    ){
        return;
    }


    const item =
        inventorySlots[
            selectedInventorySlot
        ];


    if(
        !item ||
        item.type==="potion"
    ){
        return;
    }


    const character =
        getBackpackCharacter(
            inventoryCharacterIndex
        );


    if(!character){
        return;
    }


    const equipmentKey =
        getBackpackEquipmentKey(
            inventoryCharacterIndex
        );


    const equipment =
        characterEquipment[equipmentKey];


    const equipmentSlot =
        getInventoryEquipmentSlot(item.type);


    if(!equipmentSlot){
        return;
    }


    const oldItem =
        equipment[equipmentSlot];


    if(oldItem){

        inventoryItems.push(
            oldItem
        );

    }


    const actualIndex =
        inventoryItems.indexOf(
            item
        );


    if(actualIndex>=0){

        inventoryItems.splice(
            actualIndex,
            1
        );

    }


    equipment[equipmentSlot] =
        item;


    closeItemModal();

    rebuildInventorySlots();

    renderInventory();

    updateUI();

    saveGame();

}


