function unequipItem(slot){

    const character =
        getBackpackCharacter(
            inventoryCharacterIndex
        );


    if(!character){
        return;
    }


    const equipmentKey =
        getBackpackEquipmentKey(
            inventoryCharacterIndex
        );


    const equipment =
        characterEquipment[equipmentKey];


    const item =
        equipment[slot];


    if(!item){
        return;
    }


    if(
        inventoryItems.length>=120
    ){

        alert(
            "èƒŒåŒ…å·²æ»¿ï¼Œç„¡æ³•è„«ä¸‹è£å‚™ã€‚"
        );

        return;

    }


    inventoryItems.push(
        item
    );


    equipment[slot]=null;


    closeItemModal();

    rebuildInventorySlots();

    renderInventory();

    updateUI();

    saveGame();

}


