function getZoneMonsterListHTML(zoneKey){

    const config=
        zoneConfig[zoneKey];


    if(!config){
        return"";
    }


    const zoneMonsters=

        typeof config.monsters===
        "function"
        ?
        config.monsters()
        :
        [];


    const seenNames=
        new Set();


    const lines=
        [];


    zoneMonsters.forEach(
        monster=>{

            if(
                !monster ||
                seenNames.has(
                    monster.name
                )
            ){
                return;
            }


            seenNames.add(
                monster.name
            );


            lines.push(

                monster.name+
                "Lv."+
                monster.level+
                "æ•æ·"+
                Math.round(
                    getMonsterAgility(
                        monster
                    )
                )

            );

        }
    );


    return lines
        .map(
            line=>
                "<div>"+
                line+
                "</div>"
        )
        .join("");

}


